const fs=require('fs');
const prefix='D:/备份文件夹/探域问答审核-20260905/y5aw-no-voice-20260906';
const cards=JSON.parse(fs.readFileSync(prefix+'-before.json','utf8'));
const c=cards.find(x=>x.id==='6a9a56c24a45121da4d7d000');
if(!c?.ifOpen||c.includeCondition.shop.length!==1||c.includeCondition.shop[0].thirdShopId!=='2095398963959042048')throw Error('范围不符');
const before=c.content.map(x=>x.content).join('\n');
if(!before.includes('、语音播报、智能定时'))throw Error('原文变化');
const after=before.replace('、语音播报、智能定时','、智能定时')+'\nY5AW这款是没有语音播报功能的。';
fs.writeFileSync(prefix+'-plan.json',JSON.stringify([{id:c.id,type:c.type,includeCondition:c.includeCondition,before,after}],null,2));
console.log(after);
